      } catch {
        return "(unknown task)";
      }
    },
    // resolveAuthorName: looks up the user name given a userId
    (authorId: string) => {
      try {
        return userService.getById(authorId).name;
      } catch {
        return "(unknown user)";
      }
    }
  );

  const notificationService = new NotificationService(
    eventBus,
    // resolveTaskAssignee: looks up the assigneeId for a given taskId
    (taskId: string) => {
      try {
        return taskService.getById(taskId).assigneeId;
      } catch {
        return null;
      }
    }
  );

  // ----------------------------------------------------------------
  // 3. Build router
  // ----------------------------------------------------------------
  const router = new Router(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
  );

  // ----------------------------------------------------------------
  // 4. Create HTTP server
  // ----------------------------------------------------------------
  const server = createServer((req, res) => {
    router.handle(req, res).catch((err) => {
      console.error("[Server] Unhandled error:", err);
      res.writeHead(500, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Internal server error" }));
    });
