    assert(readNotif.read === true, "Notification marked as read");

    // ── 8. Change Task Status (forward transitions) ────────────────
    section("8. Change Task Status (todo → in-progress → done)");

    const { body: inProgress } = await request<{ status: string }>(
      "PUT",
