    section("16. Delete Comment");

    const { status: deleteCommentStatus } = await request("DELETE", `/comments/${comment2.id}`);
    assert(deleteCommentStatus === 204, "Comment deleted (204)");

    const { body: task1CommentsAfter } = await request("GET", `/comments?taskId=${task1.id}`);
