for (const f of files) {
  const content = fs.readFileSync(path.join(servicesDir, f), 'utf-8');

  // RULE 1: no cross-service imports (look only at import statements, not template literals)
  // Match: import ... from "...service" or import ... from '../service...'
  const lines = content.split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('import ') && trimmed.includes('from ')) {
      const match = trimmed.match(/from\s+['"]([^'"]+)['"]/);
      if (match) {
        const mod = match[1];
        if (mod.endsWith('-service') || mod.includes('-service.')) {
          console.log('RULE1 FAIL in ' + f + ': ' + trimmed);
          rule1Pass = false;
        }
      }
    }
  }

  // RULE 2: each service has private Map store
  const hasPrivateMap = content.includes('private store: Map');
  if (!hasPrivateMap) {
    const hasAnyPrivateMap = content.includes(': Map<');
    if (!hasAnyPrivateMap) {
      console.log('RULE2 FAIL (no private Map store) in ' + f);
      rule2Pass = false;
    }
  }

  // RULE 3: no http module in services
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('import ')) {
