        console.log('RULE3 FAIL in ' + f + ': ' + trimmed);
        rule3Pass = false;
      }
    }
    if (/\bIncomingMessage\b|\bServerResponse\b/.test(trimmed)) {
      console.log('RULE3 FAIL (http type) in ' + f + ': ' + trimmed);
