const hasForwardOnly = taskContent.includes('VALID_TRANSITIONS') && taskContent.includes('allowedNext !== newStatus');
console.log('RULE 4 (forward-only status):      ' + (hasForwardOnly ? 'PASS' : 'FAIL'));

