const ALLOWED_BUILTIN = new Set([
  'http','crypto','url','events','util','stream','querystring','path','fs','buffer','net','os','assert','child_process','cluster',
  'node:http','node:crypto','node:url','node:events','node:util','node:stream','node:querystring','node:path','node:fs','node:buffer','node:net'
]);
