for (const fp of allSrcFiles) {
  const lines = fs.readFileSync(fp, 'utf-8').split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('import ') && trimmed.includes('from ')) {
      const match = trimmed.match(/from\s+['"]([^'"]+)['"]/);
      if (match) {
        const mod = match[1];
        if (mod.startsWith('.')) continue; // relative import - ok
        if (ALLOWED_BUILTIN.has(mod)) continue;
        console.log('RULE5 FAIL in ' + fp + ': unexpected import "' + mod + '"');
        rule5Pass = false;
      }
    }
  }
}
console.log('RULE 5 (no external packages):     ' + (rule5Pass ? 'PASS' : 'FAIL'));

// RULE 6: one service per file - required files exist
const serviceFiles = ['user-service.ts','project-service.ts','task-service.ts','comment-service.ts','notification-service.ts'];
let rule6Pass = serviceFiles.every(f => fs.existsSync(path.join(servicesDir, f)));
rule6Pass = rule6Pass && fs.existsSync('src/event-bus.ts') && fs.existsSync('src/router.ts') && fs.existsSync('src/main.ts') && fs.existsSync('src/demo.ts');
console.log('RULE 6 (one service per file):     ' + (rule6Pass ? 'PASS' : 'FAIL'));
